import json, numpy as np

# Load held-out eval data source
src = json.load(open('data/ultrachat_eval_heldout.json'))
print(f"Source data: {len(src)} conversations")
print(f"Keys of first conv: {list(src[0].keys()) if isinstance(src[0], dict) else type(src[0])}")

# Show structure
if isinstance(src[0], dict):
    c = src[0]
    print(f"\nExample conv 0:")
    for k, v in c.items():
        if isinstance(v, str):
            print(f"  {k}: {v[:100]}...")
        elif isinstance(v, list):
            print(f"  {k}: list of {len(v)} items, first={str(v[0])[:80]}...")
        else:
            print(f"  {k}: {v}")
elif isinstance(src[0], list):
    print(f"First conv is a list of {len(src[0])} messages")
    for m in src[0][:3]:
        if isinstance(m, dict):
            print(f"  role={m.get('role')}, content={str(m.get('content', ''))[:80]}...")
        else:
            print(f"  {str(m)[:80]}...")

# Check conversation lengths in source data
if isinstance(src[0], dict) and 'messages' in src[0]:
    lens = [len(c['messages']) for c in src]
elif isinstance(src[0], list):
    lens = [len(c) for c in src]
else:
    lens = []
if lens:
    print(f"\nSource conv lengths: min={min(lens)}, max={max(lens)}, mean={np.mean(lens):.1f}")
    from collections import Counter
    print(f"Distribution: {dict(sorted(Counter(lens).items()))}")
PYEOF
